import { test, expect } from '@playwright/test';

const BASE = process.env.WI_BASE_URL || "http://127.0.0.1:8765";
const resolveURL = (value: string) => /^https?:\/\//i.test(value)
  ? value
  : `${BASE.replace(/\/$/, '')}/${value.replace(/^\//, '')}`;

test("english-offline/TC-01 英语音频播放后留下，再次打开使用本机缓存", async ({ page }) => {
    await page.goto(resolveURL("/english/"), { waitUntil: 'domcontentloaded' });
    await page.locator("#library [data-kind='audio'] .cat-item").first().waitFor({ state: 'visible', timeout: 15000 });
    await page.locator("#library [data-kind='audio'] .cat-item").first().click();
    await page.locator("#offlineHint").first().waitFor({ state: 'visible', timeout: 15000 });
    await page.goto(resolveURL("/english/"), { waitUntil: 'domcontentloaded' });
    await page.locator("#offlineHint").first().waitFor({ state: 'visible', timeout: 15000 });
    await expect(page.locator("#offlineHint").first()).toContainText("正在使用本机缓存");
    expect(page.url()).toContain("/english/");
});
